-- ===== 0001_initial_schema.sql =====
-- 0001_initial_schema.sql
-- Book Recommender — initial schema (stage 1). See ../../DESIGN.md §6.
--
-- Integer identity PKs/FKs; `isbn` is a unique natural key, not a key column.
-- The runner (migrate.py) wraps this file in a single transaction and records it
-- in schema_migrations, so do NOT add BEGIN/COMMIT here.

-- Status of a book in a user's library.
CREATE TYPE library_status AS ENUM ('read', 'owned', 'want_to_read', 'disliked');

-- Reusable trigger function to keep updated_at current on UPDATE.
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Catalog + Open Library cache. Canonical book set, keyed internally by book_id.
CREATE TABLE books (
    book_id            integer     GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    isbn               text        NOT NULL UNIQUE,   -- ISBN-10: KB / Open Library key
    isbn13             text,                          -- unreliable; informational
    title              text        NOT NULL,
    author             text,
    description        text,                          -- blurb; embedding/resolve source
    pages              integer,
    published_year     integer,
    language           text,
    genres             text[],
    content_warnings   text[],                        -- source TBD (Q1)
    cover_url          text,
    source             text,                          -- provenance, e.g. 'openlibrary'
    details_fetched_at timestamptz,                   -- get_book_details cache freshness
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX books_genres_gin ON books USING gin (genres);
CREATE TRIGGER books_set_updated_at
    BEFORE UPDATE ON books
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Application users (UI-facing; no secrets here).
CREATE TABLE users (
    user_id      integer     GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email        text        NOT NULL UNIQUE,
    display_name text,
    created_at   timestamptz NOT NULL DEFAULT now()
);

-- Authentication sidecar, 1:1 with users (secrets kept out of the users row).
CREATE TABLE user_details (
    user_id         integer     PRIMARY KEY REFERENCES users(user_id) ON DELETE CASCADE,
    password_hash   text        NOT NULL,
    salt            text,                             -- optional (bcrypt/argon2 embed it)
    blocked_until   timestamptz,                      -- NULL = not blocked
    failed_attempts smallint    NOT NULL DEFAULT 0,
    updated_at      timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER user_details_set_updated_at
    BEFORE UPDATE ON user_details
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Unified read-list / wishlist / owned / disliked. Serves get_user_library and n8n.
CREATE TABLE user_library (
    user_id    integer        NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    book_id    integer        NOT NULL REFERENCES books(book_id) ON DELETE CASCADE,
    status     library_status NOT NULL,
    rating     smallint       CHECK (rating BETWEEN 1 AND 5),  -- set when read
    review     text,                                           -- USER review (<> KB editorial)
    added_at   timestamptz    NOT NULL DEFAULT now(),
    updated_at timestamptz    NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, book_id)
);
-- Supports the n8n "users who rated similar books highly" query.
CREATE INDEX user_library_candidate_idx ON user_library (book_id, status, rating);
CREATE TRIGGER user_library_set_updated_at
    BEFORE UPDATE ON user_library
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ===== 0002_books_authors_array.sql =====
-- 0002_books_authors_array.sql
-- Change books.author (single text) -> books.authors (text[]).
-- Decision: co-authors matter; a book can have more than one author.
-- See DESIGN.md §6. Forward-only (0001 is already applied — do not edit it).
--
-- The runner (migrate.py) wraps this file in a single transaction; no BEGIN/COMMIT.

ALTER TABLE books ADD COLUMN authors text[];

-- Carry any existing single author into the array (no-op on an empty catalog).
UPDATE books
   SET authors = ARRAY[author]
 WHERE author IS NOT NULL;

ALTER TABLE books DROP COLUMN author;

-- ===== 0003_owned_shelves.sql =====
-- 0003_owned_shelves.sql
-- Named shelves within the Owned category (see DESIGN.md §6).
-- Shelves exist only for Owned; a book may sit on several shelves (many-to-many).
-- The 4 statuses in user_library are unchanged — a book on any shelf is kept at
-- status = 'owned'; un-filing (removing from all shelves) leaves it owned.
-- Forward-only; the runner wraps this file in one transaction (no BEGIN/COMMIT).

-- A user's named Owned shelves.
CREATE TABLE shelves (
    shelf_id   integer     GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    user_id    integer     NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    name       text        NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
-- No two shelves with the same name per user (case-insensitive).
CREATE UNIQUE INDEX shelves_user_name_uq ON shelves (user_id, lower(name));
CREATE TRIGGER shelves_set_updated_at
    BEFORE UPDATE ON shelves
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Book <-> shelf membership (many-to-many).
CREATE TABLE shelf_books (
    shelf_id integer     NOT NULL REFERENCES shelves(shelf_id) ON DELETE CASCADE,
    book_id  integer     NOT NULL REFERENCES books(book_id)   ON DELETE CASCADE,
    added_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (shelf_id, book_id)
);
CREATE INDEX shelf_books_book_idx ON shelf_books (book_id);

-- ===== 0004_shelves_replace_statuses.sql =====
-- 0004_shelves_replace_statuses.sql
-- Shelves replace the four library statuses (see DESIGN.md §6).
--
--   * A book's place in a library is now only its shelves (shelf_books).
--   * Every user has exactly one built-in "Exclusion" shelf (shelves.is_exclusion):
--     its books are never used as taste and never recommended. It is created by a
--     trigger for every new user, and the API refuses to rename or delete it.
--   * A book is on Exclusion OR on normal shelves, never both: a trigger removes
--     it from the other kind when it is added to one.
--   * user_library keeps only the per-book rating and review (the n8n pipeline
--     reads ratings); the status column and its enum are dropped.
--
-- Data: disliked -> Exclusion; read -> "Read"; want_to_read -> "Want to read";
-- owned books that sit on no shelf -> "Owned". Existing named shelves are kept,
-- and a same-named shelf is reused rather than duplicated.
-- Forward-only; the runner wraps this file in one transaction (no BEGIN/COMMIT).

ALTER TABLE shelves ADD COLUMN is_exclusion boolean NOT NULL DEFAULT false;
CREATE UNIQUE INDEX shelves_one_exclusion_per_user ON shelves (user_id) WHERE is_exclusion;

-- 1) One Exclusion shelf per user (adopt a shelf already named "Exclusion").
UPDATE shelves SET is_exclusion = true WHERE lower(name) = 'exclusion';
INSERT INTO shelves (user_id, name, is_exclusion)
SELECT u.user_id, 'Exclusion', true
FROM users u
WHERE NOT EXISTS (SELECT 1 FROM shelves s WHERE s.user_id = u.user_id AND s.is_exclusion);

-- 2) Shelves for the former statuses, only where a user has such books.
INSERT INTO shelves (user_id, name)
SELECT DISTINCT ul.user_id, m.shelf_name
FROM user_library ul
JOIN (VALUES ('read'::library_status, 'Read'),
             ('want_to_read'::library_status, 'Want to read')) AS m (status, shelf_name)
  ON ul.status = m.status
WHERE NOT EXISTS (SELECT 1 FROM shelves s
                  WHERE s.user_id = ul.user_id AND lower(s.name) = lower(m.shelf_name));

INSERT INTO shelves (user_id, name)
SELECT DISTINCT ul.user_id, 'Owned'
FROM user_library ul
WHERE ul.status = 'owned'
  AND NOT EXISTS (SELECT 1 FROM shelf_books sb JOIN shelves s ON s.shelf_id = sb.shelf_id
                  WHERE s.user_id = ul.user_id AND sb.book_id = ul.book_id)
  AND NOT EXISTS (SELECT 1 FROM shelves s WHERE s.user_id = ul.user_id AND lower(s.name) = 'owned');

-- 3) Memberships. Unfiled owned books first, while "on no shelf" still means unfiled.
INSERT INTO shelf_books (shelf_id, book_id)
SELECT s.shelf_id, ul.book_id
FROM user_library ul
JOIN shelves s ON s.user_id = ul.user_id AND lower(s.name) = 'owned' AND NOT s.is_exclusion
WHERE ul.status = 'owned'
  AND NOT EXISTS (SELECT 1 FROM shelf_books sb JOIN shelves s2 ON s2.shelf_id = sb.shelf_id
                  WHERE s2.user_id = ul.user_id AND sb.book_id = ul.book_id)
ON CONFLICT DO NOTHING;

INSERT INTO shelf_books (shelf_id, book_id)
SELECT s.shelf_id, ul.book_id
FROM user_library ul
JOIN shelves s ON s.user_id = ul.user_id
 AND (   (ul.status = 'read'         AND lower(s.name) = 'read'         AND NOT s.is_exclusion)
      OR (ul.status = 'want_to_read' AND lower(s.name) = 'want to read' AND NOT s.is_exclusion)
      OR (ul.status = 'disliked'     AND s.is_exclusion))
ON CONFLICT DO NOTHING;

-- 4) Exclusion wins: an excluded book leaves every normal shelf of that user.
DELETE FROM shelf_books sb
USING shelves s
WHERE sb.shelf_id = s.shelf_id
  AND NOT s.is_exclusion
  AND EXISTS (SELECT 1 FROM shelf_books e JOIN shelves x ON x.shelf_id = e.shelf_id
              WHERE x.user_id = s.user_id AND x.is_exclusion AND e.book_id = sb.book_id);

-- 5) user_library keeps only ratings/reviews.
DROP INDEX user_library_candidate_idx;
DELETE FROM user_library WHERE rating IS NULL AND review IS NULL;
ALTER TABLE user_library DROP COLUMN status;
DROP TYPE library_status;
CREATE INDEX user_library_rating_idx ON user_library (book_id, rating);

-- 6) Rules that every write path gets for free.

-- Every new user starts with an Exclusion shelf.
CREATE FUNCTION create_exclusion_shelf() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO shelves (user_id, name, is_exclusion) VALUES (NEW.user_id, 'Exclusion', true);
    RETURN NEW;
END;
$$;
CREATE TRIGGER users_create_exclusion_shelf
    AFTER INSERT ON users
    FOR EACH ROW EXECUTE FUNCTION create_exclusion_shelf();

-- Adding a book to Exclusion takes it off the user's normal shelves, and adding
-- it to a normal shelf takes it off Exclusion.
CREATE FUNCTION shelf_books_exclusion_rule() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    target shelves%ROWTYPE;
BEGIN
    SELECT * INTO target FROM shelves WHERE shelf_id = NEW.shelf_id;
    DELETE FROM shelf_books sb
    USING shelves s
    WHERE sb.shelf_id = s.shelf_id
      AND s.user_id = target.user_id
      AND sb.book_id = NEW.book_id
      AND s.is_exclusion <> target.is_exclusion;
    RETURN NEW;
END;
$$;
CREATE TRIGGER shelf_books_exclusion
    AFTER INSERT ON shelf_books
    FOR EACH ROW EXECUTE FUNCTION shelf_books_exclusion_rule();

-- ===== 0005_agent_sessions.sql =====
-- 0005_agent_sessions.sql
-- Conversation history for the "What's my next read?" assistant (DESIGN.md §5A/§6).
--
--   * agent_sessions — one row per conversation thread. "New chat" starts another.
--   * agent_turns    — one row per TURN: the reader's input plus the agent's
--     structured output as JSON ({reply, recommendations, tool_trace, unverified,
--     notes}). The assistant loads the last AGENT_HISTORY_K *messages* (a turn is
--     two: the input and the reply) into context; all turns are persisted.
--
-- Integer identity PKs/FKs (isbn is never a key here). The runner (migrate.py)
-- wraps this file in one transaction; do NOT add BEGIN/COMMIT. set_updated_at()
-- comes from 0001.

CREATE TABLE agent_sessions (
    session_id integer     GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    user_id    integer     NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    title      text,                                   -- optional label (first message)
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX agent_sessions_user_idx ON agent_sessions (user_id, updated_at DESC);
CREATE TRIGGER agent_sessions_set_updated_at
    BEFORE UPDATE ON agent_sessions
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- One row per turn. `output` holds the whole structured reply as JSON so the
-- recommendations and tool-trace rehydrate for re-rendering a past turn; only
-- `user_input` + `output->>'reply'` are replayed into the model's context.
CREATE TABLE agent_turns (
    turn_id    integer     GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    session_id integer     NOT NULL REFERENCES agent_sessions(session_id) ON DELETE CASCADE,
    user_input text        NOT NULL,
    output     jsonb       NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX agent_turns_session_idx ON agent_turns (session_id, created_at);
